/**
 * The local database. Every read in the app comes from here, so a screen
 * renders on the first frame whether or not the network is up.
 *
 * The tables mirror the sync entities the API knows about (word, progress,
 * settings, notebook, confusion), which is what lets a pulled change be
 * applied and a local edit be pushed without translation.
 */
import Dexie, { type EntityTable } from 'dexie';
import type { Progress, Settings, Streak, Word, LanguageCode } from '@lexpad/core';
import type { ApiNudgeView, ApiSrsState, ApiSrsStats, ApiSurfaceStatus } from '@/api/types.js';

/**
 * A word as stored locally: the domain shape without the learning state,
 * which lives in its own table because it changes far more often and syncs
 * as its own entity.
 *
 * The local shapes come from `@lexpad/core`, not from the generated API
 * types. The generated types render the spec's `allOf` schemas as
 * intersections whose optional halves make required fields read as possibly
 * undefined; mapping happens once, at the network boundary in `sync/`.
 */
export type StoredWord = Omit<Word, 'progress'>;

/** A word's learning state, keyed by word id. */
export interface StoredProgress extends Progress {
  wordId: string;
}

/** A notebook as stored locally. */
export interface StoredNotebook {
  id: string;
  title: string;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  isDefault: boolean;
  sortOrder: number;
  role: string;
  wordCount: number;
  createdAt: string;
  updatedAt: string;
}

/**
 * This learner's saved schedule settings for one notebook (SRS v2), keyed by
 * the notebook id. Only saved settings live here; a notebook without a row
 * runs on the defaults the server announces (meta `srs`). It comes from the
 * snapshot and the `schedule` sync entity, and is changed only through
 * `PUT /notebooks/{id}/schedule`, never the outbox.
 */
export interface StoredSchedule {
  notebookId: string;
  scheduler: 'boxes' | 'smart';
  retention: number;
  afterMiss: 'restart' | 'back2';
  extraPractice: 'keep' | 'moves';
  /** 0 is no limit. */
  reviewCap: number;
  leechThreshold: number;
  maxInterval: number;
  params?: { w: number[]; source: 'default' | 'tuned'; tunedAt?: string; reviews?: number };
  tuning: boolean;
  updatedAt?: string;
}

/** A confusion pair count, keyed by the two ids joined with a dash. */
export interface StoredConfusion {
  key: string;
  wordA: string;
  wordB: string;
  count: number;
}

/** One day's review totals. */
export interface StoredDayStat {
  day: number;
  reviewed: number;
  correct: number;
  newWords: number;
}

/**
 * Everything that is one value per account: the signed-in user, the sync
 * cursor, the settings and the streak. Keyed so Dexie can hold them in one
 * table without a schema change every time we add one.
 */
export interface StoredMeta {
  key: keyof MetaShape;
  value: unknown;
}

/**
 * The kinds of change the outbox carries. The first five are sync entities
 * and go to `POST /sync/push`; `review` is a graded card and goes to
 * `POST /reviews`, which keeps the event itself rather than only its effect
 * on the learning state; `undo` takes back one review the server already
 * has, by its client id, through `POST /progress/{wordId}` (`undoReview`).
 * All are idempotent, and all are sent in the order they were made.
 */
export type OutboxEntity = 'word' | 'progress' | 'settings' | 'notebook' | 'confusion' | 'review' | 'undo';

/** What an `undo` item carries. */
export interface UndoPayload {
  /** The client id of the review to take back. */
  reviewClientId: string;
  /** When the learner tapped Undo, on this device's clock. */
  clientTs: string;
  /**
   * The updatedAt the word was put back to locally. A grade made after the
   * undo carries it as its token; once the server answers, those grades
   * carry the server's stamp instead (see the worker).
   */
  restoredUpdatedAt: string;
}

/** What the user did while offline, waiting to be pushed. */
export interface OutboxItem {
  /** Auto-incremented, and also the push order. */
  seq?: number;
  /** The client-generated id that makes the push idempotent. */
  clientId: string;
  entity: OutboxEntity;
  entityId: string;
  op: 'upsert' | 'delete';
  payload?: unknown;
  clientTs: string;
  /** The sync cursor the client held when it made this change. */
  baseCursor?: string;
  attempts: number;
  lastError?: string;
  /**
   * Set aside after repeated failures the item itself may be causing. A
   * parked change is never deleted: the learner's data stays local and can
   * be retried from Settings.
   */
  parked?: boolean;
  /**
   * Set on a review just before its first send. A review that was never
   * sent can be dropped by Undo without a word to the server; one that was
   * may have arrived, so Undo also asks the server to take it back.
   */
  attempted?: boolean;
}

/** The typed Dexie instance. */
export class LexpadDb extends Dexie {
  words!: EntityTable<StoredWord, 'id'>;
  progress!: EntityTable<StoredProgress, 'wordId'>;
  notebooks!: EntityTable<StoredNotebook, 'id'>;
  confusions!: EntityTable<StoredConfusion, 'key'>;
  dayStats!: EntityTable<StoredDayStat, 'day'>;
  meta!: EntityTable<StoredMeta, 'key'>;
  outbox!: EntityTable<OutboxItem, 'seq'>;
  schedules!: EntityTable<StoredSchedule, 'notebookId'>;

  constructor(name = 'lexpad') {
    super(name);
    this.version(1).stores({
      // Indexes are the ones the screens actually query on.
      words: 'id, notebookId, position, createdAt, headword',
      progress: 'wordId, dueDay, box, [retired+dueDay]',
      notebooks: 'id, sortOrder',
      confusions: 'key, count',
      dayStats: 'day',
      meta: 'key',
      outbox: '++seq, clientId, entity, [entity+entityId]',
    });
    // SRS v2: each notebook's schedule settings. Nothing is rewritten; the
    // progress table keeps its indexes and gains only unindexed fields.
    this.version(2).stores({ schedules: 'notebookId' });
  }
}

/** The database this app instance uses. */
export const db = new LexpadDb();

/** Drops every local table. Used by sign-out and by "reset". */
export async function clearLocalData(database: LexpadDb = db): Promise<void> {
  await database.transaction(
    'rw',
    [
      database.words,
      database.progress,
      database.notebooks,
      database.confusions,
      database.dayStats,
      database.meta,
      database.outbox,
      database.schedules,
    ],
    async () => {
      await Promise.all([
        database.words.clear(),
        database.progress.clear(),
        database.notebooks.clear(),
        database.confusions.clear(),
        database.dayStats.clear(),
        database.meta.clear(),
        database.outbox.clear(),
        database.schedules.clear(),
      ]);
    },
  );
}

/** Typed meta accessors, so callers do not repeat the cast. */
/** One notification in the bell's copy of the inbox. Instants are UTC ISO strings ending in Z. */
export interface InboxNotification {
  id: string;
  /** campaign, gift_ai_cards, gift_pro or comeback. */
  kind: string;
  title: string;
  body: string;
  /** An in-app path; absent opens Today. Checked with pushPath before it is followed. */
  link?: string;
  createdAt: string;
  readAt?: string;
}

/**
 * What this device remembers about the new learner's tips (meta `tips`,
 * read and written by features/learn). Tip ids are the keys of `seen`.
 */
export interface StoredTips {
  /** The local day each tip was first shown. Shown once counts as put away. */
  seen: Partial<Record<string, number>>;
  /** The day `today` counts for. */
  day: number;
  /** New tips shown on `day`. */
  today: number;
  /** "Show tips" was turned off in Settings → Practice. */
  off: boolean;
  /** Settled once: this device met tips before it had any practice history. */
  beginner: boolean;
  /** The local day tips were first settled here: the learner's first day. */
  firstDay: number;
  /** Practice sessions started since then. */
  sessions: number;
  /** Session summaries seen since then. */
  summaries: number;
  /** The last practice day before the break whose welcome-back line was shown. */
  comeback: number | null;
}

/**
 * What this device remembers about the Pro trial's few words on Today (meta
 * `trialNotes`, features/billing/trial.ts). Each moment is shown once: a
 * card or line that has been put on screen is not put there again in a later
 * visit, and one put away is gone. Dates are the server's own `endsAt` and
 * `endedAt`, so a second trial (an opt-in after the first) is a new moment.
 */
export interface StoredTrialNotes {
  /** When this device first saw a running trial: the start, if nothing better is known. */
  firstSeen?: string;
  /** The midway card ("You have Pro until…") was put on screen. */
  midwaySeen?: boolean;
  /** …and was answered (its button or Not now). */
  midwayDone?: boolean;
  /** The trial (by `endsAt`) whose "ends on" line was shown in the hero. */
  endingSeen?: string;
  /** The ended trial (by `endedAt`) whose end card was put on screen. */
  endSeen?: string;
  /** …and answered. */
  endDone?: string;
}

export interface MetaShape {
  user: {
    id: string;
    email: string;
    displayName: string;
    timezone: string;
    locale: string;
    // Added later; rows written by older builds lack them.
    emailVerified?: boolean;
    marketingOptIn?: boolean;
    providers?: readonly string[];
    createdAt?: string;
  } | null;
  cursor: string;
  settings: Settings | null;
  streak: Streak;
  activeNotebook: string | null;
  lastSyncAt: string | null;
  onboarded: boolean;
  /** Epoch milliseconds until which the confirm-e-mail banner stays hidden. */
  verifySnoozedUntil: number | null;
  /** The last read of the site's version file, for sideloaded Android builds. */
  updateCheck: { at: number; version: string; url: string } | null;
  /** A newer version the person chose not to be told about again. */
  updateDismissed: string | null;
  /** ISO instant until which AI cards are resting after the server refused a request. */
  aiPausedUntil: string | null;
  /**
   * Whether the browser extension has ever been connected to this account.
   * A milestone rather than a state: the extension marks its words like any
   * other, so the only trace it leaves is a session, and that is a network
   * read. Once seen it stays seen.
   */
  extensionSeen: boolean;
  /**
   * Whether the getting-started list is offered here, and whether finishing
   * it has been celebrated. Decided once, on the first launch that looks:
   * an account that already has words and a practice history is not new.
   */
  getStarted: { offered: boolean; celebrated: boolean } | null;
  /** Whether "Not now" was chosen on Today's offer to turn the reminder on. */
  reminderOfferDismissed: boolean;
  /**
   * Whether this install's last registration gave the server a push token.
   * While it did, the server sends the come-back notifications and the local
   * plan leaves them out, so nobody hears the same thing twice; without one
   * (no Google services, Firebase blocked, notifications refused) the phone
   * keeps sending its own, which work offline.
   */
  pushReceives: boolean;
  /**
   * The newest page of the account's notifications, for the bell on Today
   * (features/inbox). A copy of what the server holds, kept so the bell
   * draws from local data on the first frame; `unread` is the server's count
   * for the whole inbox, lowered here as things are marked read.
   */
  inbox: { notifications: InboxNotification[]; unread: number } | null;
  /**
   * The one-time card that introduces Smart on the schedule page (SRS v2
   * phase C) was put away on this device.
   */
  smartIntroSeen: boolean;
  /**
   * The one-time card on Today inviting a learner with some history to try
   * Smart (SRS v2) was answered on this device, by "See how it works" or
   * "Not now". Either way it is never shown again.
   */
  smartInviteSeen: boolean;
  /**
   * Today's line offering a daily review limit after a break (SRS v2) was
   * tapped or put away: the last day practised before that break, so the
   * next break may offer it again and this one never does twice.
   */
  capOfferDismissed: number | null;
  /**
   * How the notebook was last looked at on this device (features/notebook/viewMemory.ts).
   * Loosely typed on purpose: a value written by another build is checked on the way in.
   */
  notebookView: {
    filter: string;
    order: string;
    showMeanings?: boolean;
    showExamples?: boolean;
    level?: string;
    kind?: string;
  } | null;
  /**
   * The last answer to GET /me/surfaces ("Lexpad everywhere"), with when it
   * was read, so the hub draws on the first frame and offline says "as of".
   */
  surfaces: { at: string; list: ApiSurfaceStatus[] } | null;
  /** The last answer to GET or PUT /me/nudges: the cards' rules and history. */
  nudges: { at: string; view: ApiNudgeView } | null;
  /**
   * This app session (features/everywhere/session.ts): the app opened after
   * the server's sessionGapMinutes away starts a new one. One card a session.
   */
  appSession: { id: string; lastActiveAt: number } | null;
  /** How many times "Paste a text" or "Read a text" added words on this device. */
  pasteUses: number;
  /**
   * The last answer to GET /me/srs, with when it was read: which SRS v2
   * features this account and client may use. Null until it is first read;
   * `state` is null when the server has no such endpoint (404). Both mean
   * today's schedule and no SRS v2 screens.
   */
  srs: { at: string; state: ApiSrsState | null } | null;
  /**
   * The last answer to GET /me/srs/stats (SRS v2 phase D): "Remembered when
   * due" per notebook and what personal tuning last found, with when it was
   * read, so Progress and the schedule page draw it on the first frame and
   * say "as of" offline. Null until it is first read.
   */
  srsStats: { at: string; stats: ApiSrsStats } | null;
  /**
   * The practice modes on this device (SRS v2 phase E): whether the games
   * run without a clock (an accessibility choice), and the best Speed round
   * per notebook id. Kept here, not synced: a best score is this device's.
   */
  modes: { noTimer: boolean; speedBest: Record<string, number> } | null;
  /**
   * The new learner's tips on this device (features/learn): which were shown,
   * how many today, "Show tips", and whether this device met them as a
   * beginner. Null until settled, which happens only while the feature is on.
   * Per device on purpose: a tip seen once more on a second device is harmless,
   * and it keeps Today rendering from IndexedDB with no request.
   */
  tips: StoredTips | null;
  /**
   * Whether "More options" was left open on the schedule page and on
   * Settings → Practice, so it opens the same way next time on this device.
   */
  moreOptions: { schedule: boolean; practice: boolean } | null;
  /** The Pro trial's moments on Today, shown once each (features/billing/trial.ts). */
  trialNotes: StoredTrialNotes;
}

const META_DEFAULTS: MetaShape = {
  user: null,
  cursor: '0',
  settings: null,
  streak: { current: 0, longest: 0 },
  activeNotebook: null,
  lastSyncAt: null,
  onboarded: false,
  verifySnoozedUntil: null,
  aiPausedUntil: null,
  updateCheck: null,
  updateDismissed: null,
  extensionSeen: false,
  getStarted: null,
  reminderOfferDismissed: false,
  pushReceives: false,
  inbox: null,
  smartIntroSeen: false,
  smartInviteSeen: false,
  capOfferDismissed: null,
  notebookView: null,
  surfaces: null,
  nudges: null,
  appSession: null,
  pasteUses: 0,
  srs: null,
  srsStats: null,
  modes: null,
  tips: null,
  moreOptions: null,
  trialNotes: {},
};

/** Reads one meta value, falling back to its documented default. */
export async function getMeta<K extends keyof MetaShape>(
  key: K,
  database: LexpadDb = db,
): Promise<MetaShape[K]> {
  const row = await database.meta.get(key);
  return row === undefined ? META_DEFAULTS[key] : (row.value as MetaShape[K]);
}

/** Writes one meta value. */
export async function setMeta<K extends keyof MetaShape>(
  key: K,
  value: MetaShape[K],
  database: LexpadDb = db,
): Promise<void> {
  await database.meta.put({ key, value });
}
