/**
 * The typed HTTP client.
 *
 * Three things make it different from a bare `fetch`:
 *
 * - The access token lives in memory only. On the web the refresh token is
 *   an httpOnly cookie the browser sends for us; native shells hand us one
 *   through the platform's secure storage, which is read once at launch and
 *   waited for by anything that refreshes.
 * - A 401 triggers one refresh, shared by every request that was in flight
 *   *and by every other tab*, and the original requests are replayed once.
 *   Only a refresh the server refused ends the session; one that never
 *   arrived leaves it alone.
 * - A 403 `reauth_required` is not retried here: it reaches the screen as an
 *   ApiError, and setting a first password (Settings, Account) asks the
 *   learner to sign out and sign in again.
 * - Failures arrive as `ApiError`, never as a raw response, so screens and
 *   the outbox can decide what to do without reading status codes.
 * - Inside the desktop app (`platform.desktop`) none of the token handling
 *   runs: the app's core holds the session, sends every request with it and
 *   refreshes it, and this page never sees a token. A 401 that reaches here
 *   means the core's session has ended.
 */
import { ApiError, isApiError, kindForStatus, type Problem } from './errors.js';
import { backoffDelay, parseRetryAfter, sleep } from '@/lib/backoff.js';
import { reportError } from '@/lib/monitoring.js';
import { platform } from '@/lib/platform/index.js';

/** Called when the session ends for good, so the app can show sign-in. */
type SessionEndedListener = () => void;

export interface RequestOptions {
  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  /** JSON body. Anything else goes in `raw`. */
  body?: unknown;
  /** A non-JSON body, such as a multipart upload. */
  raw?: BodyInit;
  query?: Record<string, string | number | boolean | undefined>;
  /** Makes a retry of the same call safe; the API replays the first response. */
  idempotencyKey?: string;
  headers?: Record<string, string>;
  signal?: AbortSignal;
  /** Skips the bearer token and the refresh dance, for the auth endpoints. */
  anonymous?: boolean;
  /** Expect a file rather than JSON. */
  expect?: 'json' | 'blob' | 'void';
  /**
   * Whether an overloaded server's answer (see `transientPause`) is retried
   * here, after the wait it asked for plus jitter. Defaults to calls that
   * are safe to repeat: reads, and writes that carry an idempotency key.
   * The sync worker turns it off: its outbox keeps the work and its loop
   * has a longer backoff of its own.
   */
  retry?: boolean;
  /**
   * Lets the request outlive the page (`fetch` keepalive): the last push
   * when the tab is hidden or closed. The browser allows such bodies 64 KB
   * in all, which a push batch stays well under.
   */
  keepalive?: boolean;
}

/**
 * The wait to assume when an overloaded server's `Retry-After` cannot be
 * read. The API's CORS policy exposes only a few headers, and not this one,
 * so in a browser on app.lexpad.app this is what applies. It is the API's
 * own answer when it sheds load (two seconds: `shedRetryAfter` and
 * `BusyRetryAfter` in lexpad_back); it lives here because there is no
 * readable header to carry it.
 */
export const DEFAULT_RETRY_AFTER_MS = 2_000;

/** The first backoff window for a request retried here; it doubles each time. */
const RETRY_BASE_MS = 1_000;

/**
 * The longest one request waits here, in one pause, before its caller hears
 * about it. Screens are waiting on these calls; anything longer is the sync
 * loop's job, which keeps its work in the outbox.
 */
export const RETRY_CAP_MS = 8_000;

/** Retries of one request after an overloaded answer, beyond the first try. */
export const MAX_REQUEST_RETRIES = 2;

/**
 * Until when this tab holds every request back, after the server said it
 * was overloaded. One 503 on Today would otherwise be followed by the four
 * other calls the screen makes, each into the same overload.
 */
let pausedUntil = 0;

/**
 * How long the server asked this tab to wait, from now, in milliseconds.
 * The sync loop reads it so it does not start a run into a pause.
 */
export function serverPauseLeft(): number {
  return Math.max(0, pausedUntil - Date.now());
}

/** Forgets any pause, for tests. */
export function __resetPauseForTests(): void {
  pausedUntil = 0;
}

/**
 * Records a pause the server asked for. Each tab comes back at its own
 * moment within one more `Retry-After`: thousands of clients told "two
 * seconds" must not all return in the same instant.
 */
function notePause(retryAfterMs: number): void {
  const until = Date.now() + retryAfterMs + Math.floor(Math.random() * retryAfterMs);
  pausedUntil = Math.max(pausedUntil, until);
}

/** Waits out a pause, if one is on; never longer than `RETRY_CAP_MS`. */
async function waitOutPause(signal?: AbortSignal): Promise<void> {
  const wait = Math.min(serverPauseLeft(), RETRY_CAP_MS);
  if (wait > 0) await pauseFor(wait, signal);
}

/** A wait the caller's signal can cut short, which fails like a lost connection. */
async function pauseFor(ms: number, signal?: AbortSignal): Promise<void> {
  try {
    await sleep(ms, signal);
  } catch {
    throw new ApiError('offline', 'The request could not be sent.', 0);
  }
}

/**
 * The wait an answer asks for when it says the server is overloaded rather
 * than refusing this request: a 503 or 429 with a readable `Retry-After`,
 * a 503 the API sent while shedding load (code `busy`), or a bare 503 from
 * a proxy in front of it. A 429 or 503 with any other code is a refusal
 * (a quota, a switched-off feature) and asking again would not change it,
 * so it is undefined.
 */
function transientPause(response: Response, problem: Problem | undefined): number | undefined {
  if (response.status !== 503 && response.status !== 429) return undefined;
  const header = parseRetryAfter(response.headers.get('Retry-After'));
  if (header !== undefined) return header;
  if (response.status === 503 && (problem?.code === undefined || problem.code === 'busy')) {
    return DEFAULT_RETRY_AFTER_MS;
  }
  return undefined;
}

const API_PREFIX = '/api/v1';

let accessToken: string | null = null;
let accessTokenExpiry = 0;
let refreshToken: string | null = null;
let refreshInFlight: Promise<RefreshOutcome> | null = null;
/**
 * The name of the lock only one tab may hold while refreshing, and of the
 * channel the winner tells the others on. Both are same-origin.
 */
const REFRESH_LOCK = 'lexpad.refresh';
/** How long to wait for another tab's refresh before going ahead anyway. */
const REFRESH_LOCK_WAIT_MS = 10_000;
/** Resolves once the refresh token a native shell stored has been read. */
let storedRefreshRead: Promise<void> | null = null;
/** A removal of that token that may still be on its way to the store. */
let storedRefreshCleared: Promise<unknown> = Promise.resolve();
/**
 * Counts how often the session was forgotten. A read of the secure store
 * that was already in flight when that happened must not put the old token
 * back, so it compares the count it started with.
 */
let sessionEpoch = 0;
/**
 * Whether this tab ended its session on purpose (sign-out, or a refresh the
 * server refused). A token another tab announces must not bring it back. A
 * tab that has simply just loaded holds no token either, but it has ended
 * nothing, and adopting a sibling's token is exactly what it should do: two
 * tabs reloading together after an update both start with nothing.
 */
let sessionForgotten = false;
const sessionEndedListeners = new Set<SessionEndedListener>();
/**
 * Inside the desktop app: whether its core said it holds a session. The core
 * keeps the tokens; this is only what `hasSession` answers there.
 */
let desktopSignedIn = false;

/** Marks the desktop app's core as signed in, after it connected in the browser. */
export function noteDesktopSession(): void {
  desktopSignedIn = true;
  sessionForgotten = false;
}

/**
 * Reads the refresh token a native shell kept, once per launch.
 *
 * On the web this finds nothing and is not needed: the token is a cookie the
 * browser attaches by itself. In a shell there is no cookie, so nothing can
 * refresh until this has finished, and it is slow — it loads the plugin and
 * crosses the native bridge. Everything that might refresh waits for it,
 * because a refresh sent before it lands has no token at all, and the empty
 * refresh that follows looks exactly like a session that has ended.
 */
function readStoredRefresh(): Promise<void> {
  const epoch = sessionEpoch;
  // After a sign-out the read waits for the removal, so it can never find
  // the token that sign-out was throwing away.
  storedRefreshRead ??= storedRefreshCleared
    .then(() => platform.secure.get('refresh'))
    .then(
      (stored) => {
        // A sign-in that landed while this was in flight is newer, and a
        // sign-out means there is nothing to restore.
        if (epoch === sessionEpoch && refreshToken === null) refreshToken = stored;
      },
      (cause: unknown) => {
        // Unreadable secure storage means signing in again on every start;
        // that must reach error reporting, not vanish.
        reportError(cause, { where: 'secure-storage-read' });
      },
    );
  return storedRefreshRead;
}

/** Stores the tokens a sign-in or refresh returned. */
export function setSession(token: string, expiresInSeconds: number, refresh?: string): void {
  accessToken = token;
  sessionForgotten = false;
  // Refresh a little early, so a request never races the expiry.
  accessTokenExpiry = Date.now() + Math.max(0, expiresInSeconds - 30) * 1000;
  if (refresh !== undefined) {
    refreshToken = refresh;
    // A failed write would sign the learner out on the next start, so it is
    // reported rather than dropped.
    platform.secure.set('refresh', refresh).catch((cause: unknown) => {
      reportError(cause, { where: 'secure-storage-write' });
    });
  }
}

/** Forgets the session, locally. */
export function clearSession(): void {
  desktopSignedIn = false;
  accessToken = null;
  accessTokenExpiry = 0;
  refreshToken = null;
  sessionForgotten = true;
  sessionEpoch += 1;
  // A read still in flight must not undo this, and the next one starts
  // again — after the removal below, so it reads nothing.
  storedRefreshRead = null;
  storedRefreshCleared = platform.secure.remove('refresh').catch(() => undefined);
}

/** Whether a usable access token is held right now. */
export function hasSession(): boolean {
  return platform.desktop === undefined ? accessToken !== null : desktopSignedIn;
}

/** Notifies the app that the session ended and sign-in is required. */
export function onSessionEnded(listener: SessionEndedListener): () => void {
  sessionEndedListeners.add(listener);
  return () => sessionEndedListeners.delete(listener);
}

function endSession(): void {
  clearSession();
  for (const listener of sessionEndedListeners) listener();
}

/**
 * Restores the refresh token a native shell stored, then tries to exchange
 * it for an access token. On the web there is nothing to restore: the cookie
 * is sent automatically, so this just attempts a refresh.
 */
export async function restoreSession(): Promise<boolean> {
  if (platform.desktop !== undefined) return askDesktop(platform.desktop);
  await readStoredRefresh();
  return refresh();
}

/** Exchanges the refresh token for a new access token. One at a time. */
export async function refresh(): Promise<boolean> {
  if (platform.desktop !== undefined) return askDesktop(platform.desktop);
  return (await refreshOutcome()) === 'ok';
}

/**
 * The desktop app's core refreshes for itself; all there is to ask it is
 * whether it holds a session. A core that cannot answer holds none.
 */
async function askDesktop(host: NonNullable<typeof platform.desktop>): Promise<boolean> {
  desktopSignedIn = await host.signedIn().catch(() => false);
  return desktopSignedIn;
}

/**
 * What a refresh did. The difference matters: a server that refused the
 * token has ended the session, while a request that never arrived says
 * nothing at all, and treating the second as the first signs people out
 * over a moment of bad signal.
 */
type RefreshOutcome = 'ok' | 'rejected' | 'unreachable';

/**
 * Refreshes, at most one at a time, and one at a time across every tab.
 *
 * Refresh tokens rotate: spending one invalidates it. Holding the promise
 * in a module variable serialises the requests inside a tab, which is what
 * this used to do and is only half the problem. On the web the refresh
 * token is a cookie, and a cookie belongs to the origin rather than to the
 * tab, so two tabs that hit a 401 in the same moment each started a refresh
 * with the same token. The first rotated it, the second presented one the
 * server had already spent, and that tab was signed out mid-sentence. It
 * happened with the app open in two places and took the session down in
 * both.
 *
 * `navigator.locks` is what makes it one refresh for the origin. A tab that
 * waited usually has nothing left to do: the winner broadcasts the access
 * token it was given, and adopting that is cheaper than spending another
 * refresh token for the same thing.
 *
 * Why this design and not another:
 *
 * - The lock alone is what makes it correct on the web. The refresh cookie
 *   is updated as soon as the winner's response lands, before it lets go,
 *   so a tab that refreshes after it presents the new cookie and succeeds.
 * - The broadcast is only a saving: one rotation instead of one per tab. It
 *   carries the access token and its expiry, never a refresh token, on a
 *   same-origin channel. A tab that has just loaded adopts it too; only a
 *   tab that ended its session on purpose ignores it.
 * - A wait for the lock that times out keeps the session and reports the
 *   call as offline, because the holder is still mid-refresh and spending
 *   the same token now is what gets the session revoked.
 * - A refusal is looked at a second time under the lock before the session
 *   ends, in case a sibling's rotation slipped past the lock.
 * - The native shells run one web view, so the in-tab promise below is the
 *   whole story there: app resume, a sync and push registration all join
 *   the same refresh, and its refresh token comes from memory, which
 *   `setSession` updates before that promise settles.
 *
 * The lock and channel keep the name `lexpad.refresh` on purpose: a tab
 * still running the previous build must queue on the same lock as one
 * running this build, and an update is exactly when both are open.
 */
async function refreshOutcome(): Promise<RefreshOutcome> {
  refreshInFlight ??= refreshOnceForTheOrigin().finally(() => {
    refreshInFlight = null;
  });
  return refreshInFlight;
}

async function refreshOnceForTheOrigin(): Promise<RefreshOutcome> {
  // Whatever this tab was holding when it decided to refresh. If it has
  // changed by the time the lock is ours, another tab did the work.
  const before = accessToken;
  const first = await refreshUnderLock(before);
  if (first !== 'rejected') return first;
  // A refusal can be a race that slipped through: a browser without locks,
  // or a sibling that spent the cookie between our request leaving and the
  // lock being ours. Take the lock once more and look again before ending a
  // session: by then the sibling's token has usually arrived, or the cookie
  // is the current one. A session that has really ended is refused twice.
  return refreshUnderLock(before);
}

/**
 * One attempt, holding the origin-wide lock where there is one. Inside it,
 * a token another tab announced while we waited is adopted rather than
 * spending the refresh token again.
 */
async function refreshUnderLock(before: string | null): Promise<RefreshOutcome> {
  // Typed as optional on purpose: the DOM library says these always exist,
  // and in a web view old enough they do not.
  const locks = globalThis.navigator.locks as LockManager | undefined;
  if (locks === undefined) return adopted(before) ? 'ok' : doRefresh();
  try {
    return await locks.request(
      REFRESH_LOCK,
      { signal: AbortSignal.timeout(REFRESH_LOCK_WAIT_MS) },
      async () => (adopted(before) ? 'ok' : doRefresh()),
    );
  } catch (error) {
    if (adopted(before)) return 'ok';
    // The wait was abandoned: another tab has been holding the lock, which
    // means its refresh is still on the wire (a lock dies with its tab).
    // Spending the same token now is the very race the lock exists to
    // prevent, and the server answers it by revoking the session for every
    // tab. Report it as unreachable instead: the call fails like an offline
    // one, the session is kept, and the next call finds the new token.
    if (waitAbandoned(error)) return 'unreachable';
    // Anything else means the lock itself is broken here (an opaque origin,
    // a web view with a half-finished implementation). Refresh without it,
    // as a browser that has no locks at all does.
    return doRefresh();
  }
}

/** Whether a lock request failed because its wait ran out, not because it broke. */
function waitAbandoned(error: unknown): boolean {
  return error instanceof DOMException && (error.name === 'TimeoutError' || error.name === 'AbortError');
}

/**
 * What to do about a 401 for a request that carried `sentWith`. When the
 * token has moved on since it left — a refresh this tab shared finished
 * just before, or another tab announced one — the request is replayed with
 * the new token rather than spending the refresh token a second time.
 */
function recoverFrom401(sentWith: string | null): Promise<RefreshOutcome> {
  // The desktop app's core already refreshed and retried before answering.
  if (platform.desktop !== undefined) return Promise.resolve('rejected');
  return adopted(sentWith) ? Promise.resolve('ok') : refreshOutcome();
}

/** Whether another tab handed us a usable token while we were waiting. */
function adopted(before: string | null): boolean {
  return accessToken !== null && accessToken !== before && accessTokenExpiry > Date.now();
}

/**
 * Tells the other tabs what this one was given.
 *
 * The access token only. The refresh token is the browser's cookie or the
 * shell's secure storage, and neither needs a copy passing around.
 */
function announceSession(token: string, expiry: number): void {
  const Channel = globalThis.BroadcastChannel as typeof BroadcastChannel | undefined;
  if (Channel === undefined) return;
  try {
    const channel = new Channel(REFRESH_LOCK);
    channel.postMessage({ accessToken: token, accessTokenExpiry: expiry });
    channel.close();
  } catch {
    // A browser that refuses the channel simply refreshes for itself.
  }
}

/**
 * Listens for a token another tab was given. Started once, at import, so a
 * tab that is only reading is still carried along by one that refreshed.
 */
function listenForSession(): void {
  const Channel = globalThis.BroadcastChannel as typeof BroadcastChannel | undefined;
  if (Channel === undefined) return;
  try {
    const channel = new Channel(REFRESH_LOCK);
    channel.onmessage = (event: MessageEvent<unknown>) => {
      if (typeof event.data !== 'object' || event.data === null) return;
      const sent = event.data as { accessToken?: unknown; accessTokenExpiry?: unknown };
      if (typeof sent.accessToken !== 'string' || typeof sent.accessTokenExpiry !== 'number') return;
      // Never resurrect a session this tab has deliberately ended.
      if (sessionForgotten) return;
      if (sent.accessTokenExpiry <= Date.now()) return;
      accessToken = sent.accessToken;
      accessTokenExpiry = sent.accessTokenExpiry;
    };
  } catch {
    // Nothing to listen with; this tab refreshes for itself.
  }
}

listenForSession();

interface AuthSession {
  accessToken: string;
  expiresIn: number;
  refreshToken?: string;
}

async function doRefresh(): Promise<RefreshOutcome> {
  // The shell's token may still be on its way out of the secure store.
  await readStoredRefresh();
  try {
    const body = refreshToken === null ? undefined : { refreshToken };
    const session = await request<AuthSession>('/auth/refresh', {
      method: 'POST',
      anonymous: true,
      ...(body ? { body } : {}),
    });
    setSession(session.accessToken, session.expiresIn, session.refreshToken);
    if (accessToken !== null) announceSession(accessToken, accessTokenExpiry);
    return 'ok';
  } catch (error) {
    // Only a refusal (4xx) says the token is no good. A server that broke
    // or asked us to slow down has said nothing about the session.
    if (isApiError(error, 'offline') || isApiError(error, 'server') || isApiError(error, 'tooMany')) {
      return 'unreachable';
    }
    return 'rejected';
  }
}

function errorFor(response: Response, problem: Problem | undefined, retryAfterMs?: number): ApiError {
  const message = problem?.detail ?? problem?.title ?? `The server answered ${response.status}.`;
  return new ApiError(kindForStatus(response.status), message, response.status, problem, retryAfterMs);
}

function buildUrl(path: string, query?: RequestOptions['query']): string {
  const base = platform.env.apiUrl.replace(/\/$/, '');
  const url = `${base}${API_PREFIX}${path}`;
  if (!query) return url;
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value !== undefined && value !== '') params.set(key, String(value));
  }
  const search = params.toString();
  return search === '' ? url : `${url}?${search}`;
}

async function readProblem(response: Response): Promise<Problem | undefined> {
  try {
    const text = await response.text();
    if (text === '') return undefined;
    return JSON.parse(text) as Problem;
  } catch {
    return undefined;
  }
}

async function send(path: string, options: RequestOptions): Promise<Response> {
  const headers: Record<string, string> = { Accept: 'application/json', ...options.headers };
  if (options.body !== undefined) headers['Content-Type'] = 'application/json';
  if (options.idempotencyKey !== undefined) headers['Idempotency-Key'] = options.idempotencyKey;
  if (options.anonymous !== true && accessToken !== null) {
    headers.Authorization = `Bearer ${accessToken}`;
  }

  const init: RequestInit = {
    method: options.method ?? 'GET',
    headers,
    // Sends and accepts the refresh cookie on the web.
    credentials: 'include',
    ...(options.signal ? { signal: options.signal } : {}),
    ...(options.keepalive === true ? { keepalive: true } : {}),
  };
  if (options.raw !== undefined) init.body = options.raw;
  else if (options.body !== undefined) init.body = JSON.stringify(options.body);

  // The desktop app's core sends it, with the session only it holds.
  if (platform.desktop !== undefined) return platform.desktop.fetch(buildUrl(path, options.query), init);
  return fetch(buildUrl(path, options.query), init);
}

/**
 * Sends one request with the session: refreshes a token known to be stale
 * first, and on a 401 refreshes (or adopts a newer token) and replays once.
 * Throws `ApiError` for the network failing and the session ending; any
 * other answer comes back as it is.
 */
async function sendWithSession(path: string, options: RequestOptions): Promise<Response> {
  const needsToken = options.anonymous !== true;
  // Refresh proactively when the token is known to be stale.
  if (needsToken && accessToken !== null && Date.now() >= accessTokenExpiry) {
    await refresh();
  }

  // The token this request carries. A 401 for it says nothing about a newer
  // one another call or tab has fetched since.
  const sentWith = accessToken;
  let response: Response;
  try {
    response = await send(path, options);
  } catch {
    throw new ApiError('offline', 'The request could not be sent.', 0);
  }

  if (response.status === 401 && needsToken) {
    const outcome = await recoverFrom401(sentWith);
    // A refresh that could not be sent proves nothing about the session, so
    // the call fails as an offline one and the token is kept.
    if (outcome === 'unreachable') {
      throw new ApiError('offline', 'The request could not be sent.', 0);
    }
    if (outcome === 'rejected') {
      endSession();
      throw new ApiError('unauthenticated', 'Your session has ended.', 401);
    }
    try {
      response = await send(path, options);
    } catch {
      throw new ApiError('offline', 'The request could not be sent.', 0);
    }
    if (response.status === 401) {
      endSession();
      throw new ApiError('unauthenticated', 'Your session has ended.', 401);
    }
  }
  return response;
}

/**
 * Performs one API call and returns its parsed body. Throws `ApiError` for
 * every failure, including the network being down.
 *
 * An overloaded server (see `transientPause`) holds every request in this
 * tab back for the time it asked, with jitter, and a call that is safe to
 * repeat is tried again after an exponential backoff with full jitter, at
 * most `MAX_REQUEST_RETRIES` times. Anything still refused reaches the
 * caller with `retryAfterMs`, so a loop can wait longer.
 */
export async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const retry =
    options.retry ?? ((options.method ?? 'GET') === 'GET' || options.idempotencyKey !== undefined);
  let response: Response;
  for (let attempt = 0; ; attempt += 1) {
    await waitOutPause(options.signal);
    response = await sendWithSession(path, options);
    if (response.status !== 503 && response.status !== 429) break;
    const problem = await readProblem(response);
    const retryAfterMs = transientPause(response, problem);
    if (retryAfterMs === undefined) throw errorFor(response, problem);
    notePause(retryAfterMs);
    if (!retry || attempt >= MAX_REQUEST_RETRIES) throw errorFor(response, problem, retryAfterMs);
    await pauseFor(
      backoffDelay(attempt, { baseMs: RETRY_BASE_MS, capMs: RETRY_CAP_MS, floorMs: retryAfterMs }),
      options.signal,
    );
  }

  if (!response.ok) throw errorFor(response, await readProblem(response));

  if (options.expect === 'void' || response.status === 204) return undefined as T;
  if (options.expect === 'blob') return (await readBody(() => response.blob())) as T;
  if (response.status === 304) return undefined as T;

  const text = await readBody(() => response.text());
  if (text === '') return undefined as T;
  try {
    return JSON.parse(text) as T;
  } catch {
    throw new ApiError('server', 'The server answered with something unreadable.', response.status);
  }
}

/**
 * Reads a response body. It can be cut off after the headers arrived, by the
 * connection or by the caller's timeout; that is the network failing, the
 * same as a request that could not be sent.
 */
async function readBody<B>(read: () => Promise<B>): Promise<B> {
  try {
    return await read();
  } catch {
    throw new ApiError('offline', 'The response was cut off.', 0);
  }
}

/** Performs a call that returns no body, such as a logout or a delete. */
export async function requestVoid(path: string, options: RequestOptions = {}): Promise<void> {
  await request<undefined>(path, { ...options, expect: 'void' });
}

/** A fresh idempotency key for a mutating call. */
export function newIdempotencyKey(): string {
  return crypto.randomUUID();
}

/** Test seam: replaces the in-memory session without a network call. */
export function __setSessionForTests(token: string | null, expiresIn = 900): void {
  if (token === null) clearSession();
  else setSession(token, expiresIn);
}

/** One server-sent event: its name, its data and the id to resume from. */
export interface ServerEvent {
  event: string;
  data: string;
  id: string;
}

/**
 * Reads a server-sent event stream, calling `onEvent` for each event as it
 * arrives.
 *
 * Written here rather than with `EventSource` because EventSource cannot
 * carry an Authorization header, cannot be given a Last-Event-ID of our
 * choosing, and reconnects on its own — and a stream that silently restarts
 * would replay an answer from the beginning while the reader watches.
 *
 * The 401 dance is the same one `request` does, and for the same reason: an
 * access token can expire in the seconds between opening a screen and
 * asking for the answer on it.
 */
export async function stream(
  path: string,
  options: RequestOptions & { lastEventId?: string; onEvent: (event: ServerEvent) => void },
): Promise<void> {
  const { onEvent, lastEventId, ...rest } = options;
  const headers: Record<string, string> = { ...rest.headers, Accept: 'text/event-stream' };
  if (lastEventId !== undefined && lastEventId !== '') headers['Last-Event-ID'] = lastEventId;
  const init = { ...rest, headers };

  await waitOutPause(rest.signal);
  if (accessToken !== null && Date.now() >= accessTokenExpiry) await refresh();

  const sentWith = accessToken;
  let response: Response;
  try {
    response = await send(path, init);
  } catch {
    throw new ApiError('offline', 'The request could not be sent.', 0);
  }
  if (response.status === 401) {
    const outcome = await recoverFrom401(sentWith);
    if (outcome === 'unreachable') throw new ApiError('offline', 'The request could not be sent.', 0);
    if (outcome === 'rejected') {
      endSession();
      throw new ApiError('unauthenticated', 'Your session has ended.', 401);
    }
    response = await send(path, init);
  }
  if (!response.ok) {
    const problem = await readProblem(response);
    const retryAfterMs = transientPause(response, problem);
    if (retryAfterMs !== undefined) notePause(retryAfterMs);
    throw errorFor(response, problem, retryAfterMs);
  }
  if (response.body === null) return;

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      // Events are separated by a blank line. Anything after the last one is
      // half an event, and waits for the rest of it.
      let split = buffer.indexOf('\n\n');
      while (split !== -1) {
        const block = buffer.slice(0, split);
        buffer = buffer.slice(split + 2);
        const parsed = parseEvent(block);
        if (parsed !== null) onEvent(parsed);
        split = buffer.indexOf('\n\n');
      }
    }
  } finally {
    // Nothing to do if the reader was already gone.
    reader.cancel().catch(() => undefined);
  }
}

function parseEvent(block: string): ServerEvent | null {
  let event = 'message';
  let id = '';
  const data: string[] = [];
  for (const line of block.split('\n')) {
    // A line beginning with a colon is a comment, which is how a server
    // keeps a quiet connection open.
    if (line === '' || line.startsWith(':')) continue;
    const colon = line.indexOf(':');
    const field = colon === -1 ? line : line.slice(0, colon);
    const value = colon === -1 ? '' : line.slice(colon + 1).replace(/^ /, '');
    if (field === 'event') event = value;
    else if (field === 'id') id = value;
    else if (field === 'data') data.push(value);
  }
  if (data.length === 0 && event === 'message') return null;
  return { event, id, data: data.join('\n') };
}
